// Meetings with external guests that start soon and were not briefed yet.
const state = $getWorkflowStaticData('global');
state.briefed = state.briefed || {};
const internal = String($env.INTERNAL_EMAIL_DOMAIN || '').toLowerCase();
const now = Date.now();
for (const [id, ts] of Object.entries(state.briefed)) if (now - ts > 7 * 864e5) delete state.briefed[id];  // keep it small

const out = [];
for (const { json: e } of $input.all()) {
  if (!e.start?.dateTime || state.briefed[e.id]) continue;          // skip all-day and already briefed
  const guests = (e.attendees || []).map(a => String(a.email).toLowerCase())
    .filter(a => !a.endsWith('@' + internal) && !a.includes('resource.calendar'));
  if (!guests.length) continue;                                      // internal-only meeting
  state.briefed[e.id] = now;
  out.push({ json: {
    eventId: e.id, title: e.summary ?? '(no title)', start: e.start.dateTime, description: e.description ?? '',
    guests, gmail_query: `(from:(${guests.join(' OR ')}) OR to:(${guests.join(' OR ')})) newer_than:60d`,
  } });
}
return out;

// Recent emails with the guests, compacted, plus the request for the model.
const event = $('Loop over meetings').item.json;
const mails = ($json.emails || []).filter(m => m.id).slice(0, 15).map(m =>
  `- ${m.date ?? ''} | ${m.from?.text ?? m.From ?? ''} | ${m.subject ?? m.Subject ?? ''}: ` +
  String(m.snippet ?? m.text ?? '').replace(/\s+/g, ' ').slice(0, 300)
).join('\n') || '(no recent emails)';

const schema = {
  type: 'object', additionalProperties: false,
  properties: {
    context: { type: 'string' },
    last_interaction: { type: 'string' },
    open_topics: { type: 'array', items: { type: 'string' } },
    suggested_agenda: { type: 'array', items: { type: 'string' } },
    watch_out: { type: 'string' },
  },
  required: ['context', 'last_interaction', 'open_topics', 'suggested_agenda', 'watch_out'],
};

return [{ json: {
  event,
  openai_payload: {
    model: $env.OPENAI_MODEL || 'gpt-5.6-luna',
    instructions: 'Prepare a short briefing for an upcoming meeting from the recent email history with the guests. ' +
      'Only use facts from the emails and the event; if there is little history, say so. Write in ' +
      ($env.BRIEFING_LANGUAGE || 'Spanish') + '.',
    input: `Meeting: ${event.title}\nStarts: ${event.start}\nGuests: ${event.guests.join(', ')}\n` +
      `Description: ${event.description}\n\nRecent emails:\n${mails}`,
    text: { format: { type: 'json_schema', name: 'meeting_briefing', strict: true, schema } },
  },
} }];

function parseResponse(res) {
  const message = (res.output || []).find(o => o.type === 'message');
  const part = message?.content?.find(c => c.type === 'output_text' || c.type === 'refusal');
  if (!part || part.type === 'refusal') throw new Error('The model returned no usable answer: ' + JSON.stringify(res).slice(0, 300));
  return JSON.parse(part.text);
}

const e = $('Build briefing request').item.json.event;
const b = parseResponse($json);
const list = (title, items) => items.length ? `<h3>${title}</h3><ul>${items.map(i => `<li>${i}</li>`).join('')}</ul>` : '';
const when = new Date(e.start).toLocaleString('es-ES', { timeZone: $env.GENERIC_TIMEZONE || 'Europe/Madrid' });
return [{ json: {
  subject: `📅 Briefing: ${e.title} (${when})`,
  html: `<div style="font-family:Arial,sans-serif;max-width:680px">
<p><b>${e.title}</b> · ${when}<br>Guests: ${e.guests.join(', ')}</p>
<p>${b.context}</p><p><b>Last interaction:</b> ${b.last_interaction}</p>
${list('Open topics', b.open_topics)}${list('Suggested agenda', b.suggested_agenda)}
${b.watch_out ? `<p>⚠️ <b>Watch out:</b> ${b.watch_out}</p>` : ''}</div>`,
} }];
